'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const K = nextInt();
const U = nextInt();

const cards = new Int32Array(N * K);
for (let i = 0; i < cards.length; i++) cards[i] = nextInt();

const position = new Int32Array(U + 1);
for (let i = 1; i <= U; i++) {
  position[nextInt()] = i;
}

let best = U + 1;
const winners = [];

for (let i = 0; i < N; i++) {
  let last = 0;
  const start = i * K;
  for (let j = 0; j < K; j++) {
    const drawPosition = position[cards[start + j]];
    if (drawPosition > last) last = drawPosition;
  }

  if (last < best) {
    best = last;
    winners.length = 0;
    winners.push(i + 1);
  } else if (last === best) {
    winners.push(i + 1);
  }
}

process.stdout.write(winners.join(' '));
